from pathlib import Path
H=Path(__file__).resolve().parent;out=H/'animation_v2';ap=argparse.ArgumentParser();ap.add_argument('--frames-dir',type=Path,required=True);a=ap.parse_args();samples=json.loads((out/'frame_samples.json').read_text());fps=samples['fps'];frames=samples['frames'];N=len(frames)
def ass_time(t):
 h=int(t//3600);m=int(t//60)%60;s=int(t)%60;cs=int((t-int(t))*100+1e-7)
