now=datetime.datetime.now(datetime.timezone.utc);r={'schema':'gtsd-native-motion-video-v1','completed_utc':now.isoformat(),'completed_beijing':now.astimezone(datetime.timezone(datetime.timedelta(hours=8))).isoformat(),'file':mp4.name,'bytes':mp4.stat().st_size,'sha256':hashlib.sha256(mp4.read_bytes()).hexdigest(),'source_protocol':samples['source_protocol'],'source_case':samples['source_case'],'runtime_identity_sha256':samples['runtime_identity_sha256'],'assembly_identity_sha256':samples['assembly_identity_sha256'],'source_pose_stream_sha256':samples['source_pose_stream_sha256'],'native_duration_s':samples['native_duration_s'],'native_steps_total':samples['native_steps_total'],'display_duration_s':float(probe['format']['duration']),'fps':fps,'frame_count':N,'slow_playback_factor':samples['slow_playback_factor'],'resolution':[720,450],'codec':'H.264 / yuv420p','mesh_count':268,'pose_interpolation':False,'image_postprocess':{'filter':'ffmpeg nlmeans=s=12:p=7:r=15','scope':'independent spatial denoise within each frame','temporal_blending':False,'raw_frame_hash_records':['frame_render_0000.json','frame_render_0001.json']},'geometry_reduced':False,'solver_rerun':False,'displacement_scale':1.,'numeric_status':'V2 recorded motion; corrected numerical acceptance tracked separately','keyframe_review_files_local_only':True,'keyframes':[{k:v for k,v in record.items() if k!='file'} for record in records]};(out/'VIDEO_MANIFEST.json').write_text(json.dumps(r,indent=2)+'\n');(out/'ffprobe.json').write_text(json.dumps(probe,indent=2)+'\n');print(json.dumps(r,indent=2))
